const item = $input.first();
const binaryKeys = Object.keys(item.binary ?? {});
const binaryProperty = binaryKeys.includes('data') ? 'data' : binaryKeys[0];
if (!binaryProperty) {
  throw new Error('Desired blocklist file does not contain binary data');
}
const raw = (await this.helpers.getBinaryDataBuffer(0, binaryProperty)).toString('utf8');
if (!raw.length) {
  throw new Error('Desired blocklist file is empty');
}
const desiredLines = String(raw)
  .split(/\r?\n/)
  .map((line) => String(line).trim())
  .filter(Boolean)
  .filter((line) => /^([a-f0-9]{64})\s+SHA256_[A-Z0-9_]+$/i.test(line));
return {
  json: {
    desired_lines: [...new Set(desiredLines)].sort(),
    desired_count: [...new Set(desiredLines)].length,
    reconcile_started_at: new Date().toISOString()
  }
};

const apiKey = String($env.SOC_BITDEFENDER_API_KEY || '').trim();
const companyId = String($env.SOC_BITDEFENDER_COMPANY_ID || '').trim();
const incidentsUrl = String($env.SOC_BITDEFENDER_INCIDENTS_V12_URL || '').trim();
const licensingUrl = String($env.SOC_BITDEFENDER_LICENSING_V10_URL || '').trim();
const desiredLines = Array.isArray($json.desired_lines) ? $json.desired_lines : [];
if (!apiKey || !companyId || !incidentsUrl || !licensingUrl) {
  throw new Error('Missing Bitdefender environment configuration');
}
const chunkSize = Math.max(1, Number($env.SOC_BITDEFENDER_ADD_CHUNK_SIZE || '100'));
const intervalMs = Math.max(0, Number($env.SOC_BITDEFENDER_ADD_INTERVAL_SECONDS || '15')) * 1000;
const auth = Buffer.from(`${apiKey}:`).toString('base64');
const headers = {
  Authorization: `Basic ${auth}`,
  'Content-Type': 'application/json',
  Accept: 'application/json'
};
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const callJsonRpc = async (url, method, params, id) => {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers,
    body: {
      jsonrpc: '2.0',
      method,
      params,
      id
    },
    json: true
  });
  if (response?.error) {
    throw new Error(`${method} error ${response.error.code}: ${response.error.message}`);
  }
  return response?.result;
};
const desiredMap = new Map();
for (const line of desiredLines) {
  const match = String(line).match(/^([a-f0-9]{64})\s+(SHA256_[A-Z0-9_]+)$/i);
  if (!match) continue;
  desiredMap.set(match[1].toLowerCase(), match[2].toUpperCase());
}
await callJsonRpc(licensingUrl, 'getLicenseInfo', { returnAllProducts: true }, `soc-bitdefender-license-${Date.now()}`);
const fetchActualHashes = async () => {
  let page = 1;
  let pagesCount = 1;
  const hashes = new Set();
  do {
    const result = await callJsonRpc(incidentsUrl, 'getBlocklistItems', { companyId, page, perPage: 100 }, `soc-bitdefender-list-${Date.now()}-${page}`);
    const items = Array.isArray(result?.items) ? result.items : [];
    pagesCount = Number(result?.pagesCount || 1);
    for (const item of items) {
      if (String(item?.type || '').toLowerCase() !== 'hash') continue;
      const details = item?.details || {};
      if (String(details?.algorithm || '').toLowerCase() !== 'sha256') continue;
      const hash = String(details?.hash || '').trim().toLowerCase();
      if (/^[a-f0-9]{64}$/.test(hash)) {
        hashes.add(hash);
      }
    }
    page += 1;
  } while (page <= pagesCount);
  return hashes;
};
let actualHashes = await fetchActualHashes();
const missing = [...desiredMap.keys()].filter((hash) => !actualHashes.has(hash));
const addedBatches = [];
for (let i = 0; i < missing.length; i += chunkSize) {
  const batch = missing.slice(i, i + chunkSize);
  const rules = batch.map((hash) => ({
    note: `SOC|source=hash_sha256.txt|tag=${desiredMap.get(hash)}`,
    details: {
      algorithm: 'sha256',
      hash
    }
  }));
  const requestId = `soc-bitdefender-reconcile-${Date.now()}-${i / chunkSize + 1}`;
  const result = await callJsonRpc(incidentsUrl, 'addToBlocklist', { companyId, type: 'hash', rules, recursive: false }, requestId);
  if (result !== true) {
    throw new Error(`Unexpected addToBlocklist result for batch ${i / chunkSize + 1}`);
  }
  addedBatches.push({ request_id: requestId, count: batch.length });
  if (i + chunkSize < missing.length && intervalMs > 0) {
    await sleep(intervalMs);
  }
}
actualHashes = await fetchActualHashes();
const confirmedHashes = [...desiredMap.keys()]
  .filter((hash) => actualHashes.has(hash))
  .sort();
const confirmedLines = confirmedHashes.map((hash) => `${hash} ${desiredMap.get(hash)}`);
const confirmedCount = confirmedHashes.length;
const pendingAfter = [...desiredMap.keys()].filter((hash) => !actualHashes.has(hash));
const nowIso = new Date().toISOString();
const today = new Date();
const yyyy = today.getUTCFullYear();
const mm = String(today.getUTCMonth() + 1).padStart(2, '0');
const dd = String(today.getUTCDate()).padStart(2, '0');
return [{
  json: {
    known_present_text: confirmedHashes.length ? `${confirmedHashes.join('\n')}\n` : '',
    full_status_json: JSON.stringify({
      scope: 'daily_reconcile',
      reconcile_started_at: $json.reconcile_started_at,
      reconcile_completed_at: nowIso,
      desired_count: desiredMap.size,
      actual_confirmed_count: confirmedCount,
      missing_before_count: missing.length,
      pending_after_count: pendingAfter.length,
      added_batches: addedBatches
    }, null, 2),
    audit_json: JSON.stringify({
      scope: 'daily_reconcile',
      reconcile_started_at: $json.reconcile_started_at,
      reconcile_completed_at: nowIso,
      desired_lines: desiredLines,
      confirmed_lines: confirmedLines,
      confirmed_hashes: confirmedHashes,
      missing_before_count: missing.length,
      pending_after: pendingAfter,
      added_batches: addedBatches
    }, null, 2),
    audit_key: `gravityzone/audit/bitdefender-reconcile-${yyyy}-${mm}-${dd}.json`
  }
}];
